#!/usr/bin/env bash
# Restore the stopped original Pocket voice after Amir cutover.
# Only the voice container and private application voice config are changed.
set -Eeuo pipefail
umask 077
test "$EUID" -eq 0 || { echo "Run as root" >&2; exit 1; }
exec 9>/run/lock/forza-voice-promote.lock
flock -w 8 9 || { echo "Another FORZA voice operation is running" >&2; exit 1; }
APP=/opt/sanatpish
SITE=sanatpish-new
LIVE=forza-voice
MARKER=/etc/sanatpish/forza-amir-rollback-container
CONFIG="$APP/.env.forza-voice"
test -r "$MARKER" && test -r "$CONFIG"
# Parse only names generated by this script, not executable shell code.
BACKUP=$(sed -n 's/^BACKUP=//p' "$MARKER" | head -1)
ENV_BACKUP=$(sed -n 's/^ENV_BACKUP=//p' "$MARKER" | head -1)
case "$BACKUP" in forza-voice-before-amir-[0-9]*) ;; *) echo "Invalid rollback container name" >&2; exit 1;; esac
case "$ENV_BACKUP" in /etc/sanatpish/forza-amir-env-before-[0-9]*) ;; *) echo "Invalid backup path" >&2; exit 1;; esac
test -r "$ENV_BACKUP"
test "$(docker inspect -f '{{.State.Running}}' "$SITE")" = true
test "$(docker inspect -f '{{.State.Running}}' "$LIVE")" = true
test "$(docker inspect -f '{{.State.Running}}' "$BACKUP")" = false
docker inspect "$BACKUP" >/dev/null
echo "[1/3] Stop Amir and restore the original Pocket container."
docker stop -t 15 "$LIVE" >/dev/null
docker rename "$LIVE" "forza-amir-before-rollback-$(date -u +%Y%m%d%H%M%S)"
docker rename "$BACKUP" "$LIVE"
docker start "$LIVE" >/dev/null
echo "[2/3] Restore original private app voice engine settings."
cp -p "$ENV_BACKUP" "$CONFIG"
chmod 600 "$CONFIG"
docker restart "$SITE" >/dev/null
echo "[3/3] Verify Pocket is healthy and the catalog API remains running."
READY=0
for i in $(seq 1 60); do
  if docker exec "$SITE" node -e \
    'fetch("http://forza-voice:8080/health",{signal:AbortSignal.timeout(2500)}).then(async r=>process.exit(r.ok&&(await r.json()).voice==="pocket-farsi-v2"?0:1)).catch(()=>process.exit(1))' >/dev/null 2>&1 \
    && curl -fsS --max-time 4 http://127.0.0.1:3001/api/health 2>/dev/null | grep -q '"database":"ok"'; then
    READY=1; break
  fi
  sleep 2
done
test "$READY" = 1 || {
  echo "Pocket restored, but health verification failed; inspect logs" >&2
  exit 1
}
rm -f -- "$MARKER"
echo "FORZA_POCKET_RESTORED; original voice settings restored; database untouched."
